mapper.select:
SELECT historyPrice.opposite AS vender, SUM(historyPrice.product_rmb_total_price) AS total, SUM(historyPrice.product_quantity) AS received, COALESCE(SUM(contractMoneyRecord.record_amount), 0) AS paymentTotal FROM ${historyPriceTableName} historyPrice LEFT JOIN ${signedContractTableName} signedContract ON historyPrice.signed_contract = signedContract.primary_key LEFT JOIN ${contractMoneyRecordTableName} contractMoneyRecord ON signedContract.primary_key = contractMoneyRecord.signed_contract WHERE historyPrice.enterprise_code = #{enterpriseCode} AND historyPrice.type = 3
AND historyPrice.record_time >= #{startDate}
AND historyPrice.record_time <= #{endDate}
GROUP BY historyPrice.opposite ORDER BY total DESC
